begin;
set local search_path=public,extensions;
select plan(20);
select is((select enabled from passage_automation_policy where id),false,'Automation starts disabled');
select throws_ok($q$update passage_automation_policy set enabled=true$q$,null,'automation_calibration_required','Cannot enable without evidence');
insert into auth.users(id,email) values('b3500000-0000-4000-8000-000000000001','auto-review-a@test.invalid'),('b3500000-0000-4000-8000-000000000002','auto-review-b@test.invalid'),('b3500000-0000-4000-8000-000000000003','auto-student@test.invalid');
update profiles set role='content_reviewer' where auth_user_id in ('b3500000-0000-4000-8000-000000000001','b3500000-0000-4000-8000-000000000002');
insert into content_reviewer_profiles(profile_id,active,invite_status) select id,true,'active' from profiles where auth_user_id in ('b3500000-0000-4000-8000-000000000001','b3500000-0000-4000-8000-000000000002');
insert into students(id,profile_id) select 'b3500000-0000-4000-8000-000000000004',id from profiles where auth_user_id='b3500000-0000-4000-8000-000000000003' on conflict(profile_id) do update set id=excluded.id;
-- Synthetic calibration evidence is ONLY used inside this rolled-back test.
insert into passage_automation_calibrations(id,pipeline_version,evaluator_model,report,passed) values('b3510000-0000-4000-8000-000000000001','selective-passage-1','test-independent','{"reviewedCases":6,"negativeCases":2,"falseAccepts":0,"acceptedCases":1}',true);
update passage_automation_policy set calibration_id='b3510000-0000-4000-8000-000000000001',evaluator_model='test-independent',reviewer_ids=(select array_agg(id) from profiles where auth_user_id in ('b3500000-0000-4000-8000-000000000001','b3500000-0000-4000-8000-000000000002')),cohort_percent=100,exposure_cap=1;
select lives_ok('update passage_automation_policy set enabled=true','Calibrated bounded policy can enable');
select throws_ok($q$update passage_automation_policy set reviewer_ids=array[reviewer_ids[1],reviewer_ids[1]]$q$,null,'automation_calibration_required','Duplicate reviewers cannot satisfy sampling ownership');
select throws_ok($q$update passage_automation_calibrations set passed=false$q$,null,'automated_evidence_is_immutable','Calibration evidence is immutable');
insert into ai_generated_candidates(id,candidate_type,payload,review_status) values('b3520000-0000-4000-8000-000000000001','reading_text','{"generated":{"title":"Test arbre","body":"Un arbre pousse dans le jardin.","questions":[{"questionText":"Où ?","correctAnswer":"Jardin","answerFormat":"multiple_choice","choices":["Jardin","Maison"]}]}}','needs_human_review');
insert into passage_qa_runs(id,candidate_id,pipeline_version,payload_snapshot,evaluator_model,decision,report) select 'b3530000-0000-4000-8000-000000000001',id,'selective-passage-1',payload,'test-independent','pass','{}' from ai_generated_candidates where id='b3520000-0000-4000-8000-000000000001';
select throws_ok($q$update passage_qa_runs set decision='reject'$q$,null,'automated_evidence_is_immutable','QA evidence is immutable');
select set_config('request.jwt.claim.role','authenticated',true);
select throws_ok($q$select authorize_automated_passage('b3530000-0000-4000-8000-000000000001','b3520000-0000-4000-8000-000000000001')$q$,'42501','service_role_required','Students and editors cannot invoke automated approval');
select set_config('request.jwt.claim.role','service_role',true);
select lives_ok($q$select authorize_automated_passage('b3530000-0000-4000-8000-000000000001','b3520000-0000-4000-8000-000000000001')$q$,'Matching fresh evidence authorizes publication');
update ai_generated_candidates set payload=jsonb_set(payload,'{generated,title}','"Changed"') where id='b3520000-0000-4000-8000-000000000001';
select throws_ok($q$select authorize_automated_passage('b3530000-0000-4000-8000-000000000001','b3520000-0000-4000-8000-000000000001')$q$,null,'automated_publication_not_authorized','Edited candidate invalidates QA');
update ai_generated_candidates set payload=(select payload_snapshot from passage_qa_runs where id='b3530000-0000-4000-8000-000000000001') where id='b3520000-0000-4000-8000-000000000001';
insert into texts(id,canonical_title,slug) values('b3540000-0000-4000-8000-000000000001','Test arbre','automation-test-only');
insert into text_versions(id,text_id,version_number,title,body,generation_type,review_status) values('b3550000-0000-4000-8000-000000000001','b3540000-0000-4000-8000-000000000001',1,'Test arbre','Un arbre pousse dans le jardin.','ai_automated','draft');
select throws_ok($q$update text_versions set review_status='auto_approved' where id='b3550000-0000-4000-8000-000000000001'$q$,null,'automated_evidence_required','Cannot directly invent an automated approval');
insert into questions(id,text_version_id,question_key,question_text,question_type,answer_format,correct_answer) values('b3560000-0000-4000-8000-000000000001','b3550000-0000-4000-8000-000000000001','q1','Où ?','literal','multiple_choice','Maison');
insert into question_choices(question_id,choice_index,choice_text,is_correct) values('b3560000-0000-4000-8000-000000000001',0,'Jardin',true),('b3560000-0000-4000-8000-000000000001',1,'Maison',false);
select throws_ok($q$select finalize_automated_passage('b3530000-0000-4000-8000-000000000001','b3550000-0000-4000-8000-000000000001')$q$,null,'automated_publication_payload_mismatch','Wrong materialized answer key blocks publication');
update questions set correct_answer='Jardin' where id='b3560000-0000-4000-8000-000000000001';
select lives_ok($q$select finalize_automated_passage('b3530000-0000-4000-8000-000000000001','b3550000-0000-4000-8000-000000000001')$q$,'Exact evaluated passage can publish');
select is((select review_status from text_versions where id='b3550000-0000-4000-8000-000000000001'),'auto_approved','Automated approval does not claim human approval');
select throws_ok($q$update questions set correct_answer='Maison' where id='b3560000-0000-4000-8000-000000000001'$q$,null,'automated_questions_are_immutable','Published answer keys remain bound to QA');
select lives_ok($q$insert into reading_sessions(student_id,text_version_id) values('b3500000-0000-4000-8000-000000000004','b3550000-0000-4000-8000-000000000001')$q$,'First exposure in cohort is permitted');
select throws_ok($q$insert into reading_sessions(student_id,text_version_id) values('b3500000-0000-4000-8000-000000000004','b3550000-0000-4000-8000-000000000001')$q$,null,'automated_passage_cohort_or_cap','Exposure cap cannot be bypassed by direct insert');
select is((select exposure_count from automated_passage_publications where text_version_id='b3550000-0000-4000-8000-000000000001'),1,'Failed exposure does not consume capacity');
insert into content_review_versions(id,candidate_id,version_number,payload,workflow_status,publication_origin,published_text_version_id)
select 'b3570000-0000-4000-8000-000000000001',id,1,jsonb_set(payload,'{generated,body}',to_jsonb(repeat('Un arbre pousse dans le jardin. ',5))),'published','automated','b3550000-0000-4000-8000-000000000001' from ai_generated_candidates where id='b3520000-0000-4000-8000-000000000001';
insert into review_assignments(id,review_version_id,reviewer_profile_id) select 'b3580000-0000-4000-8000-000000000001','b3570000-0000-4000-8000-000000000001',id from profiles where auth_user_id='b3500000-0000-4000-8000-000000000001';
insert into passage_reviews(assignment_id,reviewer_profile_id,status,overall_decision) select id,reviewer_profile_id,'submitted','reject' from review_assignments where id='b3580000-0000-4000-8000-000000000001';
select is((select withdrawn from automated_passage_publications where text_version_id='b3550000-0000-4000-8000-000000000001'),true,'Adverse sample review withdraws automatic content');
update passage_automation_policy set enabled=false;
select throws_ok($q$select authorize_automated_passage('b3530000-0000-4000-8000-000000000001','b3520000-0000-4000-8000-000000000001')$q$,null,'automated_publication_not_authorized','Kill switch blocks publication');
select lives_ok($q$select rollback_automated_passage('b3530000-0000-4000-8000-000000000001')$q$,'Failed publication can reconcile');
select * from finish();
rollback;
